from orders.db import get_conn


def get_order(order_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, customer_id, total_cents, status FROM orders WHERE id = :order_id",
            {"order_id": order_id},
        )
    finally:
        conn.close()
    if not rows:
        return None
    r = rows[0]
    return {"id": r["id"], "customer_id": r["customer_id"], "total_cents": r["total_cents"], "status": r["status"]}


def list_orders_for_customer(customer_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, total_cents, status FROM orders WHERE customer_id = :customer_id ORDER BY id",
            {"customer_id": customer_id},
        )
    finally:
        conn.close()
    return [{"id": r["id"], "total_cents": r["total_cents"], "status": r["status"]} for r in rows]


def create_order(customer_id, total_cents):
    conn = get_conn()
    try:
        conn.execute(
            "INSERT INTO orders (customer_id, total_cents, status) VALUES (:customer_id, :total_cents, 'new')",
            {"customer_id": customer_id, "total_cents": total_cents},
        )
        new_id = conn.execute("SELECT max(id) AS id FROM orders")[0]["id"]
    finally:
        conn.close()
    return new_id
